css:
.myctl{
  --bg: #09100c;
  --bg-2: #0d1711;
  --panel: rgba(17, 31, 22, .72);
  --panel-2: rgba(12, 23, 16, .88);
  --line: rgba(167, 214, 177, .16);
  --line-strong: rgba(167, 214, 177, .28);
  --text: #eff7ef;
  --muted: #9eb1a2;
  --green: #8bd49a;
  --green-2: #b9ed9d;
  --moss: #496b4d;
  --brown: #967255;
  --nut: #d2a66e;
  --cream: #e8e0cb;
  --shadow: 0 24px 70px rgba(0,0,0,.34);
  --radius: 22px;
  --mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  --sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
min-height:100vh;}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
.myctl{
  margin: 0;
  color: var(--text);
  font-family: var(--sans);
  background:
    radial-gradient(circle at 10% 10%, rgba(70, 117, 74, .18), transparent 28rem),
    radial-gradient(circle at 88% 18%, rgba(143, 102, 65, .11), transparent 24rem),
    linear-gradient(180deg, #08100b 0%, #0b130e 42%, #08100b 100%);
  line-height: 1.55;
  overflow-x: hidden;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .17;
  background-image:
    linear-gradient(rgba(255,255,255,.015) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.012) 1px, transparent 1px);
  background-size: 48px 48px;
  mask-image: linear-gradient(to bottom, black, transparent 78%);
  z-index: -1;
}

a { color: inherit; text-decoration: none; }
button, a { -webkit-tap-highlight-color: transparent; }

.wrap { width: min(1180px, calc(100% - 40px)); margin: 0 auto; }

.nav {
  position: sticky;
  top: 0;
  z-index: 30;
  backdrop-filter: blur(18px);
  background: rgba(7, 13, 9, .72);
  border-bottom: 1px solid var(--line);
}
.nav-inner {
  min-height: 66px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px;
}
.brand {
  display: flex;
  align-items: center;
  gap: 11px;
  font-weight: 800;
  letter-spacing: -.02em;
}
.nut-mark {
  width: 30px;
  height: 30px;
  border-radius: 46% 54% 52% 48% / 58% 45% 55% 42%;
  background: linear-gradient(145deg, #d7b47b, #8d6645 68%, #5c422f);
  border: 1px solid rgba(255,255,255,.18);
  box-shadow: inset -6px -8px 12px rgba(49,30,18,.32), inset 5px 4px 10px rgba(255,239,199,.18);
  transform: rotate(-18deg);
  position: relative;
  flex: 0 0 auto;
}
.nut-mark::after {
  content: "";
  position: absolute;
  width: 2px;
  height: 17px;
  border-radius: 10px;
  background: rgba(74,48,28,.7);
  left: 14px;
  top: 6px;
  transform: rotate(20deg);
}
.nav-links { display: flex; gap: 18px; color: var(--muted); font-size: 14px; }
.nav-links a:hover { color: var(--text); }
.nav-cta {
  border: 1px solid var(--line-strong);
  padding: 9px 13px;
  border-radius: 999px;
  color: var(--cream);
  font-size: 13px;
  background: rgba(255,255,255,.025);
}

.hero {
  padding: 92px 0 62px;
  position: relative;
}
.eyebrow {
  font: 700 12px/1 var(--mono);
  letter-spacing: .16em;
  text-transform: uppercase;
  color: var(--green);
  margin-bottom: 22px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.08fr .92fr;
  gap: 54px;
  align-items: center;
}
h1 {
  margin: 0;
  max-width: 780px;
  font-size: clamp(52px, 8vw, 104px);
  line-height: .9;
  letter-spacing: -.07em;
  font-weight: 900;
}
h1 .mycelium { color: var(--cream); }
h1 .taproot { color: var(--green-2); }
.lede {
  max-width: 700px;
  margin: 26px 0 0;
  font-size: clamp(18px, 2vw, 23px);
  line-height: 1.5;
  color: #c8d6ca;
  letter-spacing: -.02em;
}
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-top: 31px; }
.btn {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  padding: 0 16px;
  border-radius: 12px;
  font-weight: 760;
  font-size: 14px;
  border: 1px solid var(--line-strong);
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}
.btn:hover { transform: translateY(-2px); border-color: rgba(185,237,157,.5); }
.btn.primary { color: #0a120c; background: var(--green-2); border-color: var(--green-2); }
.btn.secondary { background: rgba(255,255,255,.035); }

.root-card {
  position: relative;
  min-height: 450px;
  border: 1px solid var(--line-strong);
  border-radius: 28px;
  background:
    radial-gradient(circle at 50% 5%, rgba(158, 217, 139, .13), transparent 45%),
    linear-gradient(180deg, rgba(17,30,21,.96), rgba(7,14,9,.95));
  box-shadow: var(--shadow);
  overflow: hidden;
}
.root-card .caption {
  position: absolute;
  top: 18px;
  left: 20px;
  right: 20px;
  display: flex;
  justify-content: space-between;
  color: var(--muted);
  font: 700 11px/1 var(--mono);
  letter-spacing: .11em;
  text-transform: uppercase;
}
.network-stage { position: absolute; inset: 56px 20px 28px; }
.node {
  position: absolute;
  display: grid;
  place-items: center;
  border: 1px solid var(--line-strong);
  background: rgba(13, 27, 18, .96);
  box-shadow: 0 12px 30px rgba(0,0,0,.35), inset 0 0 0 1px rgba(255,255,255,.025);
  color: var(--cream);
  font: 760 12px/1.15 var(--mono);
  text-align: center;
  letter-spacing: -.03em;
}
.node.core {
  width: 126px; height: 126px; border-radius: 50%;
  left: 50%; top: 44%; transform: translate(-50%,-50%);
  border-color: rgba(185,237,157,.42);
  background: radial-gradient(circle at 35% 30%, #24412b, #102016 70%);
  color: var(--green-2);
  font-size: 14px;
}
.node.tap { width: 104px; height: 104px; border-radius: 50%; left: 50%; top: 8%; transform: translateX(-50%); color: var(--nut); }
.node.n1 { width: 88px; height: 88px; border-radius: 50%; left: 5%; top: 53%; }
.node.n2 { width: 88px; height: 88px; border-radius: 50%; right: 5%; top: 52%; }
.node.n3 { width: 82px; height: 82px; border-radius: 50%; left: 18%; bottom: 2%; }
.node.n4 { width: 82px; height: 82px; border-radius: 50%; right: 18%; bottom: 2%; }
.wire { position: absolute; height: 1px; background: linear-gradient(90deg, transparent, rgba(139,212,154,.42), transparent); transform-origin: left center; }
.w1 { width: 115px; left: 49%; top: 38%; transform: rotate(-91deg); }
.w2 { width: 165px; left: 24%; top: 58%; transform: rotate(-13deg); }
.w3 { width: 165px; left: 61%; top: 54%; transform: rotate(15deg); }
.w4 { width: 144px; left: 32%; top: 61%; transform: rotate(49deg); }
.w5 { width: 144px; left: 61%; top: 61%; transform: rotate(132deg); }
.pulse {
  position: absolute;
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--green-2);
  box-shadow: 0 0 0 6px rgba(185,237,157,.08), 0 0 18px rgba(185,237,157,.7);
  left: 50%; top: 43%;
  animation: breathe 2.4s ease-in-out infinite;
}
@keyframes breathe { 50% { transform: scale(1.5); opacity: .66; } }

section { padding: 74px 0; }
.section-head { margin-bottom: 32px; max-width: 820px; }
.kicker { color: var(--green); font: 700 12px/1 var(--mono); letter-spacing: .13em; text-transform: uppercase; }
h2 { margin: 11px 0 13px; font-size: clamp(34px, 5vw, 62px); line-height: 1.02; letter-spacing: -.055em; }
.section-copy { color: var(--muted); font-size: 18px; max-width: 760px; }

.split { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(19,34,24,.72), rgba(9,18,12,.82));
  padding: 28px;
  min-height: 250px;
}
.card:hover { border-color: var(--line-strong); }
.card .icon { font-size: 28px; margin-bottom: 18px; }
.card h3 { margin: 0 0 10px; font-size: 26px; letter-spacing: -.035em; }
.card p { margin: 0; color: var(--muted); }
.pill-row { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 20px; }
.pill { font: 650 11px/1 var(--mono); color: #c9ddcc; border: 1px solid var(--line); border-radius: 999px; padding: 8px 10px; background: rgba(255,255,255,.025); }

.why-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }
.why-card { min-height: 300px; position: relative; overflow: hidden; }
.why-card strong { display: block; font-size: 23px; letter-spacing: -.03em; margin: 10px 0 10px; }
.why-card .num { font: 700 11px/1 var(--mono); color: var(--green); letter-spacing: .12em; }
.why-card::after {
  content: ""; position: absolute; width: 160px; height: 160px; right: -70px; bottom: -70px;
  border: 1px solid var(--line); border-radius: 50%; box-shadow: 0 0 0 28px rgba(151,186,157,.02), 0 0 0 56px rgba(151,186,157,.015);
}

.failure {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 26px;
  align-items: stretch;
  margin-top: 30px;
}
.failure-panel { border: 1px solid var(--line); border-radius: 20px; padding: 24px; background: rgba(7,14,9,.56); }
.failure-title { font: 700 12px/1 var(--mono); text-transform: uppercase; letter-spacing: .1em; margin-bottom: 18px; color: var(--muted); }
.mini-net { min-height: 190px; display: grid; place-items: center; position: relative; }
.central { padding: 12px 16px; border: 1px solid rgba(210,166,110,.38); color: var(--nut); border-radius: 12px; font: 700 12px var(--mono); }
.sat-row { display: flex; gap: 10px; justify-content: center; margin-top: 24px; }
.sat { border: 1px solid var(--line); padding: 9px 10px; border-radius: 9px; color: var(--muted); font: 650 11px var(--mono); }
.vs { align-self: center; font: 800 11px var(--mono); color: #66776a; letter-spacing: .1em; }
.mesh { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; width: min(260px,100%); }
.mesh .sat { color: #c6d6c9; border-color: rgba(139,212,154,.25); text-align: center; }

.utility-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }
.utility {
  min-height: 162px;
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 18px;
  background: rgba(10,20,13,.7);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.utility code { font: 700 12px/1.3 var(--mono); color: var(--green-2); word-break: break-word; }
.utility span { color: var(--muted); font-size: 13px; }
.utility:hover { transform: translateY(-2px); border-color: var(--line-strong); }

.status {
  display: inline-flex; gap: 7px; align-items: center;
  font: 700 11px/1 var(--mono); text-transform: uppercase; letter-spacing: .08em;
  color: #c6d5c8; margin-bottom: 13px;
}
.status::before { content: ""; width: 7px; height: 7px; border-radius: 50%; background: var(--green); box-shadow: 0 0 0 4px rgba(139,212,154,.08); }
.status.planned::before { background: #7f8b80; box-shadow: none; }
.status.planned { color: #8d998e; }

.architecture {
  border: 1px solid var(--line-strong);
  border-radius: 26px;
  padding: 28px;
  background: rgba(6,13,8,.8);
  overflow: hidden;
}
.arch-flow { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; align-items: center; }
.arch-box { border: 1px solid var(--line); border-radius: 14px; min-height: 94px; display: grid; place-items: center; text-align: center; padding: 13px; font: 700 12px/1.3 var(--mono); background: rgba(255,255,255,.02); }
.arch-box.highlight { border-color: rgba(185,237,157,.38); color: var(--green-2); }
.arrow { color: #536557; text-align: center; font: 800 18px var(--mono); }

.repo-row { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.repo {
  border: 1px solid var(--line-strong);
  border-radius: 20px;
  padding: 24px;
  background: rgba(11,22,14,.82);
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.repo h3 { margin: 0; font-size: 30px; letter-spacing: -.04em; }
.repo .label { color: var(--green); font: 700 11px/1 var(--mono); letter-spacing: .12em; text-transform: uppercase; }
.repo .url { color: #c9d8cb; font: 600 12px/1.4 var(--mono); word-break: break-all; }

.note {
  border-left: 2px solid var(--brown);
  padding: 14px 0 14px 18px;
  color: #c9d0c9;
  max-width: 800px;
}

.final {
  margin-top: 20px;
  border-top: 1px solid var(--line);
  padding: 84px 0 90px;
  text-align: center;
}
.final h2 { max-width: 940px; margin-left: auto; margin-right: auto; }
.final p { color: var(--muted); font-size: 18px; max-width: 720px; margin: 18px auto 0; }
footer { border-top: 1px solid var(--line); padding: 28px 0 40px; color: #7f9082; font-size: 13px; }
.footer-row { display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; }

@media (max-width: 900px) {
  .nav-links { display: none; }
  .hero { padding-top: 64px; }
  .hero-grid, .split, .repo-row { grid-template-columns: 1fr; }
  .root-card { min-height: 400px; }
  .why-grid { grid-template-columns: 1fr; }
  .utility-grid { grid-template-columns: repeat(2, 1fr); }
  .failure { grid-template-columns: 1fr; }
  .vs { transform: rotate(90deg); justify-self: center; }
  .arch-flow { grid-template-columns: 1fr; }
  .arrow { transform: rotate(90deg); }
}

@media (max-width: 560px) {
  .wrap { width: min(100% - 24px, 1180px); }
  .hero { padding-top: 48px; }
  h1 { font-size: clamp(48px, 18vw, 74px); }
  .lede { font-size: 18px; }
  section { padding: 56px 0; }
  .card { padding: 22px; }
  .utility-grid { grid-template-columns: 1fr; }
  .root-card { min-height: 350px; }
  .node.tap { width: 84px; height: 84px; }
  .node.core { width: 104px; height: 104px; }
  .node.n1,.node.n2 { width: 70px; height: 70px; }
  .node.n3,.node.n4 { width: 66px; height: 66px; }
  .network-stage { left: 8px; right: 8px; }
  .hero-actions .btn { width: 100%; justify-content: center; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .001ms !important; animation-iteration-count: 1 !important; scroll-behavior: auto !important; transition: none !important; }
}


/* Orchard × Mycelium sync — public Taproot earth palette, ivory surfaces, green only for live-state accents */
.myctl{
  --bg: #160D07;
  --bg-2: #1D110A;
  --panel: #241610;
  --panel-2: #2C1B12;
  --line: rgba(212,166,118,.30);
  --line-strong: rgba(232,181,110,.48);
  --text: #FAF3E6;
  --muted: rgba(250,243,230,.66);
  --green: #8FBC6F;
  --green-2: #8FBC6F;
  --moss: #66513A;
  --brown: #8A6238;
  --nut: #E8B56E;
  --cream: #FAF3E6;
  --ivory: #FAF3E6;
  --ivory-2: #FFFDF7;
  --ink: #2B1D12;
  --bark: #C8A27A;
  --gold: #E8B56E;
  --shadow: 0 24px 70px rgba(0,0,0,.34);
}

.myctl{
  color: var(--cream);
  background:
    radial-gradient(circle at 14% 7%, rgba(232,181,110,.09), transparent 28rem),
    radial-gradient(circle at 86% 16%, rgba(200,162,122,.07), transparent 25rem),
    linear-gradient(180deg, #160D07 0%, #1B1009 46%, #160D07 100%);
}
body::before {
  opacity: .14;
  background-image:
    linear-gradient(rgba(250,243,230,.018) 1px, transparent 1px),
    linear-gradient(90deg, rgba(250,243,230,.014) 1px, transparent 1px);
}
h1,h2,h3,.brand { font-family: Georgia, "Times New Roman", serif; font-weight: 600; }
h1 { letter-spacing: -.055em; }
h1 .mycelium { color: var(--ivory); }
h1 .taproot { color: var(--gold); }
.lede { color: rgba(250,243,230,.78); }

.nav {
  background: color-mix(in srgb, #160D07 90%, transparent);
  border-bottom-color: var(--line);
}
.brand { color: var(--gold); letter-spacing: .01em; }
.nav-links { color: var(--bark); }
.nav-links a:hover { color: var(--ivory); }
.nav-cta { color: var(--gold); background: rgba(250,243,230,.025); border-color: var(--line); }
.nav-cta:hover { border-color: var(--gold); }
.nut-mark {
  background: linear-gradient(145deg, #E8B56E, #A9701F 65%, #69441F);
  border-color: rgba(250,243,230,.20);
}

.eyebrow,.kicker,.repo .label,.why-card .num { color: var(--gold); }
.btn { border-color: var(--line); }
.btn:hover { border-color: var(--gold); }
.btn.primary { color: #241610; background: var(--gold); border-color: var(--gold); }
.btn.secondary { color: var(--ivory); background: rgba(250,243,230,.035); }

.source-strip {
  display:flex; align-items:center; gap:9px; flex-wrap:wrap; margin-top:18px;
  color:var(--bark); font:650 11px/1.4 var(--mono); letter-spacing:.01em;
}
.source-strip a { color:var(--gold); }
.source-strip .sep { opacity:.55; }
.live-dot { width:7px; height:7px; border-radius:50%; background:var(--green); box-shadow:0 0 0 4px rgba(143,188,111,.10); }

.root-card {
  border-color: var(--line);
  background:
    radial-gradient(circle at 50% 4%, rgba(232,181,110,.12), transparent 43%),
    linear-gradient(180deg, #2C1B12, #1A0F09);
}
.node { background:#241610; color:var(--ivory); border-color:var(--line); }
.node.core {
  background: radial-gradient(circle at 34% 30%, #FFFDF7, #EEDFC8 76%);
  color:var(--ink); border-color:rgba(250,243,230,.70);
  box-shadow:0 12px 30px rgba(0,0,0,.34), inset 0 0 0 1px rgba(43,29,18,.06);
}
.node.tap { color:var(--gold); border-color:rgba(232,181,110,.50); }
.wire { background:linear-gradient(90deg,transparent,rgba(232,181,110,.42),transparent); }
.pulse { background:var(--green); box-shadow:0 0 0 6px rgba(143,188,111,.08),0 0 18px rgba(143,188,111,.55); }

.card {
  background:linear-gradient(180deg,rgba(44,27,18,.82),rgba(36,22,16,.90));
  border-color:var(--line);
}
.card p,.section-copy { color:var(--muted); }
.pill { color:var(--bark); background:rgba(250,243,230,.025); border-color:var(--line); }
.failure-panel,.utility,.architecture,.repo { background:#241610; border-color:var(--line); }
.central { color:var(--gold); border-color:rgba(232,181,110,.45); }
.vs,.arrow { color:#8A6B4D; }
.mesh .sat { color:var(--bark); border-color:var(--line); }
.utility code { color:var(--gold); }
.repo .url { color:var(--bark); }
.arch-box { background:rgba(250,243,230,.025); border-color:var(--line); }
.arch-box.highlight { border-color:rgba(232,181,110,.52); color:var(--gold); }
.note { border-left-color:var(--gold); color:rgba(250,243,230,.78); }

/* Ivory Mycelium surfaces: brown/ivory contrast instead of green-on-green */
#why, #agents, #build {
  background:var(--ivory);
  color:var(--ink);
  border-top:1px solid rgba(140,100,60,.20);
  border-bottom:1px solid rgba(140,100,60,.20);
}
#why .section-copy,#agents .section-copy,#build .section-copy { color:rgba(43,29,18,.66); }
#why .kicker,#agents .kicker,#build .kicker { color:#A9701F; }
#why .card,#why .failure-panel,#agents .utility,#build .repo {
  background:var(--ivory-2);
  color:var(--ink);
  border-color:rgba(140,100,60,.24);
  box-shadow:0 8px 24px rgba(120,80,40,.07);
}
#why .card p,#why .failure-panel,#agents .utility span,#build .repo p { color:rgba(43,29,18,.66); }
#why .why-card .num,#build .repo .label,#agents .utility code { color:#A9701F; }
#why .sat { color:rgba(43,29,18,.62); border-color:rgba(140,100,60,.24); }
#why .mesh .sat { color:#5E432B; border-color:rgba(140,100,60,.24); }
#why .failure-title { color:rgba(43,29,18,.55); }
#why .central { color:#8A6238; border-color:rgba(140,100,60,.34); }
#why .vs { color:#9B7B5B; }
#agents .utility:hover,#build .repo:hover { border-color:#A9701F; }
#build .repo .url { color:#8A6238; }

.status { color:var(--bark); }
.status::before { background:var(--green); box-shadow:0 0 0 4px rgba(143,188,111,.10); }
.status.planned::before { background:#8C7D70; box-shadow:none; }
.status.planned { color:#9D8C7C; }

.final { background:linear-gradient(180deg,#1B1009,#160D07); }
footer { color:rgba(250,243,230,.52); border-top-color:var(--line); }
.footer-links { display:flex; gap:14px; flex-wrap:wrap; justify-content:flex-end; }
.footer-links a { color:var(--bark); }
.footer-links a:hover { color:var(--gold); }

@media (max-width:560px) {
  .source-strip { font-size:10px; }
  .footer-links { justify-content:flex-start; }
}


/* Diagram refinement: framework is software, nodes are deployments, federation is the network. */
.root-card.refined { min-height: 500px; padding: 54px 14px 12px; }
.root-card.refined .caption { z-index: 2; }
.network-svg,.architecture-svg { display:block; width:100%; height:auto; overflow:visible; }
.network-svg { max-height: 430px; }
.svg-framework { fill:#F6ECDD; stroke:rgba(250,243,230,.82); stroke-width:1.5; }
.svg-node,.arch-node { fill:#241610; stroke:rgba(212,166,118,.36); stroke-width:1.5; }
.taproot-node { stroke:rgba(232,181,110,.82); fill:#2B1A10; }
.svg-protocol { fill:rgba(232,181,110,.06); stroke:rgba(232,181,110,.46); stroke-width:1.5; }
.svg-person { fill:rgba(250,243,230,.035); stroke:rgba(212,166,118,.28); stroke-width:1.2; }
.svg-line,.svg-fed-line { fill:none; stroke:rgba(200,162,122,.44); stroke-width:1.5; }
.svg-fed-line { stroke-dasharray:4 6; }
.svg-peer-arrow { fill:none; stroke:rgba(232,181,110,.68); stroke-width:1.35; }
.svg-title,.svg-node-title,.arch-big { font-family:var(--mono); font-size:18px; font-weight:800; fill:#FAF3E6; letter-spacing:.02em; }
.svg-title { font-size:20px; }
.svg-sub { font-family:var(--mono); font-size:12px; font-weight:650; fill:rgba(250,243,230,.65); }
.svg-label,.svg-step { font-family:var(--mono); font-size:10px; font-weight:800; fill:#C8A27A; letter-spacing:.12em; }
.svg-mini { font-family:var(--mono); font-size:9.5px; font-weight:650; fill:rgba(250,243,230,.56); }
.svg-mini.strong { fill:#FAF3E6; font-weight:800; letter-spacing:.06em; }
.svg-mini.live { fill:#8FBC6F; font-weight:850; letter-spacing:.12em; }
.dark { fill:#2B1D12 !important; }
.gold { fill:#E8B56E !important; }

.refined-architecture { padding:22px; }
.architecture-svg { min-width:760px; }
.refined-architecture { overflow-x:auto; scrollbar-width:thin; scrollbar-color:#8A6238 transparent; }
.arch-main-box { fill:rgba(250,243,230,.018); stroke:rgba(212,166,118,.30); stroke-width:1.5; }
.framework-box { fill:#F6ECDD; stroke:rgba(250,243,230,.76); }
.arch-big { font-size:20px; }
.arch-chip { fill:rgba(250,243,230,.035); stroke:rgba(212,166,118,.28); stroke-width:1; }
.arch-chip.light { fill:#FFF9EF; stroke:rgba(140,100,60,.20); }
.protocol-chip { fill:#2C1B12; stroke:rgba(232,181,110,.52); }
.arch-chip-text { font-family:var(--mono); font-size:10px; font-weight:850; fill:#FAF3E6; letter-spacing:.05em; }
.arch-arrow-line { fill:none; stroke:rgba(200,162,122,.55); stroke-width:1.5; }
.network-link { fill:none; stroke:rgba(232,181,110,.42); stroke-width:1.5; }
.network-dot { fill:#241610; stroke:rgba(212,166,118,.42); stroke-width:1.5; }
.tap-dot { stroke:#E8B56E; fill:#2B1A10; }
.arch-network-caption { font:700 11px var(--mono); fill:#C8A27A; }

.peer-section { padding-top:44px; padding-bottom:76px; }
.peer-card { border:1px solid rgba(232,181,110,.42); border-radius:28px; padding:34px; background:linear-gradient(145deg,#2A180F,#1B1009); box-shadow:var(--shadow); }
.peer-copy { display:grid; grid-template-columns:minmax(0,.9fr) minmax(0,1.1fr); gap:28px; align-items:end; }
.peer-copy .kicker { grid-column:1/-1; margin-bottom:-10px; }
.peer-copy h2 { margin:0; font-size:clamp(34px,4.4vw,58px); }
.peer-copy p { margin:0; color:var(--muted); font-size:17px; max-width:620px; }
.peer-rule { margin-top:28px; border:1px solid var(--line); border-radius:20px; padding:24px; background:rgba(250,243,230,.025); }
.peer-rule-top { display:flex; justify-content:space-between; align-items:center; gap:14px; flex-wrap:wrap; margin-bottom:14px; }
.peer-rule .status { margin:0; }
.peer-auto { color:var(--gold); font:800 10px var(--mono); letter-spacing:.12em; }
.peer-rule strong { display:block; max-width:920px; font:600 clamp(20px,2.5vw,30px)/1.25 Georgia,"Times New Roman",serif; color:var(--ivory); }
.peer-rule p { max-width:920px; color:var(--muted); margin:12px 0 0; }
.policy-note { font-size:13px; border-left:2px solid rgba(232,181,110,.48); padding-left:14px; }
.peer-result { display:grid; grid-template-columns:auto 1fr auto 1fr; gap:10px 16px; align-items:center; margin-top:22px; padding:18px 20px; border-top:1px solid var(--line); border-bottom:1px solid var(--line); }
.peer-result span { font:800 9px var(--mono); letter-spacing:.12em; color:var(--bark); }
.peer-result strong { font:700 13px var(--mono); color:var(--ivory); }
.peer-actions { display:flex; gap:12px; flex-wrap:wrap; margin-top:22px; }
.final-pre { margin:0 auto 18px; max-width:760px; color:var(--bark); font-size:15px; }
.final h2 { font-size:clamp(42px,6vw,78px); line-height:1.03; letter-spacing:-.05em; }

@media (max-width:780px) {
  .root-card.refined { min-height:auto; padding-top:52px; }
  .network-svg { max-height:none; }
  .peer-copy { grid-template-columns:1fr; gap:14px; }
  .peer-copy .kicker { margin-bottom:2px; }
  .peer-result { grid-template-columns:1fr; gap:6px; }
  .peer-result span:not(:first-child) { margin-top:10px; }
}
@media (max-width:560px) {
  .root-card.refined { padding-left:4px; padding-right:4px; }
  .root-card.refined .caption { font-size:9px; }
  .peer-card { padding:24px 18px; border-radius:22px; }
  .peer-rule { padding:19px 16px; }
  .peer-actions .btn { width:100%; justify-content:center; }
  .final h2 { font-size:clamp(40px,12vw,58px); }
}
